<?php require dirname(__DIR__).'/app/bootstrap.php';require_admin();$id=(int)($_GET['id']??0);$error='';$allowed=['pending'=>['pending','confirmed','cancelled'],'confirmed'=>['confirmed','processing','cancelled'],'processing'=>['processing','shipped','cancelled'],'shipped'=>['shipped','delivered'],'delivered'=>['delivered'],'cancelled'=>['cancelled']];
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{db()->beginTransaction();$o=query('SELECT * FROM orders WHERE id=? FOR UPDATE',[$id])->fetch();if(!$o)throw new DomainException('Order not found.');$status=(string)($_POST['status']??'');$pay=(string)($_POST['payment_status']??'');$fee=trim((string)($_POST['delivery_fee']??''));if(!in_array($status,$allowed[$o['status']]??[],true)||!in_array($pay,['unpaid','paid'],true)||($fee!==''&&(!ctype_digit($fee)||(int)$fee>100000)))throw new DomainException('Invalid status or delivery fee.');$fee=$fee===''?null:(int)$fee;if(in_array($status,['shipped','delivered'],true)&&$fee===null)throw new DomainException('Set the agreed delivery fee before shipping.');if($pay==='paid'&&($fee===null||$status==='cancelled'))throw new DomainException('A paid order must have a final total and cannot be cancelled.');if($o['payment_status']==='paid'&&$status==='cancelled')throw new DomainException('Resolve the payment outside this system and mark it unpaid before cancelling.');
if($status==='cancelled'&&$o['status']!=='cancelled'){$items=query('SELECT * FROM order_items WHERE order_id=?',[$id])->fetchAll();foreach($items as $line)if($line['stock_reserved'])query('UPDATE variants SET stock=stock+? WHERE product_id=? AND size=? AND stock IS NOT NULL',[$line['quantity'],$line['product_id'],$line['size']]);}
query('UPDATE orders SET status=?,payment_status=?,delivery_fee=?,total=? WHERE id=?',[$status,$pay,$fee,$fee===null?null:(int)$o['subtotal']+$fee,$id]);db()->commit();flash('Order updated.');redirect('admin/order.php?id='.$id);
}catch(DomainException $e){if(db()->inTransaction())db()->rollBack();$error=$e->getMessage();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}}
$o=query('SELECT * FROM orders WHERE id=?',[$id])->fetch();if(!$o){http_response_code(404);exit('Order not found.');}$items=query('SELECT * FROM order_items WHERE order_id=?',[$id])->fetchAll();render_header($o['reference'],true); ?>
<main class="page"><a class="back-link" href="<?=url('admin/index.php')?>">← ALL ORDERS</a><h1><?=h($o['reference'])?></h1><?php if($error):?><p class="notice error"><?=h($error)?></p><?php endif ?><div class="checkout-layout"><section><h2>Customer & delivery</h2><div class="summary-box"><h3><?=h($o['customer_name'])?></h3><p><?=h($o['phone'])?><br><?=h($o['email'])?></p><p><?=nl2br(h($o['address']))?><br><?=h($o['area'])?></p><p><strong>Notes:</strong> <?=nl2br(h($o['notes']))?></p><p>Placed: <?=h($o['created_at'])?></p></div><h2>Items</h2><?php foreach($items as $line):?><div class="summary-line"><span><?=h($line['product_name'])?> · <?=h($line['size'])?> × <?=h($line['quantity'])?></span><strong><?=money($line['quantity']*$line['unit_price'])?></strong></div><?php endforeach ?><div class="summary-line"><span>Product subtotal</span><strong><?=money($o['subtotal'])?></strong></div><div class="summary-line"><span>Delivery</span><strong><?=$o['delivery_fee']===null?'Awaiting agreement':money($o['delivery_fee'])?></strong></div><div class="summary-line total"><span>Total</span><strong><?=$o['total']===null?'Pending delivery fee':money($o['total'])?></strong></div></section><aside class="summary-box"><h2>Manage order</h2><form method="post"><?=csrf_input()?><label>Status<select name="status"><?php foreach($allowed[$o['status']] as $s):?><option value="<?=$s?>" <?=$s===$o['status']?'selected':''?>><?=ucfirst($s)?></option><?php endforeach ?></select></label><label>Agreed delivery fee (BDT)<input name="delivery_fee" type="number" min="0" max="100000" value="<?=h($o['delivery_fee'])?>"></label><label>Payment status<select name="payment_status"><option value="unpaid" <?=$o['payment_status']==='unpaid'?'selected':''?>>Unpaid</option><option value="paid" <?=$o['payment_status']==='paid'?'selected':''?>>Paid — verified manually</option></select></label><p class="hint">Mark paid only after confirming receipt. Cancelling an unshipped order returns tracked stock once. Cancelled orders cannot be reopened.</p><button class="button dark">SAVE CHANGES ↗</button></form></aside></div></main><?php render_footer(); ?>
